	"github.com/gravitational/teleport/lib/events"
	"github.com/gravitational/teleport/lib/utils"
	"github.com/jonboulle/clockwork"
	"github.com/stretchr/testify/require"
)

type mockDynamo struct {
	items      map[string]map[string]*dynamodb.AttributeValue
	indexes    []string
	lastQuery  *dynamodb.QueryInput
	lastUpdate map[string]*dynamodb.AttributeValue
	srv        *httptest.Server
	t          *testing.T
}

func newMock(t *testing.T, indexes []string) (*mockDynamo, *dynamodb.DynamoDB) {
	m := &mockDynamo{
		items:   map[string]map[string]*dynamodb.AttributeValue{},
		indexes: indexes,
		t:       t,
	}
	m.srv = httptest.NewServer(http.HandlerFunc(m.handle))
	t.Cleanup(func() { m.srv.Close() })
	sess, err := awssession.New(&aws.Config{
		Region:      aws.String("us-east-1"),
		Endpoint:    aws.String(m.srv.URL),
		Credentials: credentials.NewStaticCredentials("id", "secret", ""),
		MaxRetries:  aws.Int(1),
	})
	require.NoError(t, err)
	return m, dynamodb.New(sess)
}

func itemKey(item map[string]*dynamodb.AttributeValue) string {
	return fmt.Sprintf("%v/%v", aws.StringValue(item[keySessionID].S), aws.StringValue(item[keyEventIndex].N))
}

func (m *mockDynamo) sortedKeys() []string {
	var keys []string
	for k := range m.items {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func fail(w http.ResponseWriter, err error) {
	w.Header().Set("Content-Type", "application/x-amz-json-1.0")
	w.WriteHeader(http.StatusBadRequest)
	json.NewEncoder(w).Encode(map[string]string{"__type": "ValidationException", "message": err.Error()})
}

func (m *mockDynamo) handle(w http.ResponseWriter, r *http.Request) {
	body, err := ioutil.ReadAll(r.Body)
	require.NoError(m.t, err)
	target := r.Header.Get("X-Amz-Target")
	require.True(m.t, len(target) > 0, "missing target")
	_, op, found := splitTarget(target)
	require.True(m.t, found, target)
	var out interface{}
	switch op {
	case "PutItem":
		var in dynamodb.PutItemInput
		require.NoError(m.t, json.Unmarshal(body, &in))
		m.items[itemKey(in.Item)] = in.Item
		out = &dynamodb.PutItemOutput{}
	case "DescribeTable":
		var gsis []*dynamodb.GlobalSecondaryIndexDescription
		for _, name := range m.indexes {
			gsis = append(gsis, &dynamodb.GlobalSecondaryIndexDescription{IndexName: aws.String(name)})
		}
		out = &dynamodb.DescribeTableOutput{Table: &dynamodb.TableDescription{
			TableName:              aws.String("events"),
			GlobalSecondaryIndexes: gsis,
		}}
	case "Scan":
		var in dynamodb.ScanInput
		require.NoError(m.t, json.Unmarshal(body, &in))
		var items []map[string]*dynamodb.AttributeValue
		for _, k := range m.sortedKeys() {
			items = append(items, m.items[k])
		}
		out = &dynamodb.ScanOutput{Items: items, Count: aws.Int64(int64(len(items)))}
	case "UpdateItem":
		var in dynamodb.UpdateItemInput
		require.NoError(m.t, json.Unmarshal(body, &in))
		// exactly one string value has to be bound
		require.Len(m.t, in.ExpressionAttributeValues, 1)
		for _, v := range in.ExpressionAttributeValues {
			require.NotNil(m.t, v.S)
		}
		m.lastUpdate = in.ExpressionAttributeValues
		key := itemKey(in.Key)
		item, ok := m.items[key]
		if !ok {
			fail(w, fmt.Errorf("ResourceNotFoundException"))
			return
		}
		for _, v := range in.ExpressionAttributeValues {
			item[keyDate] = &dynamodb.AttributeValue{S: v.S}
		}
		out = &dynamodb.UpdateItemOutput{}
	case "Query":
		in := &dynamodb.QueryInput{}
		require.NoError(m.t, json.Unmarshal(body, in))
		m.lastQuery = in
		var date string
		var bounds []int64
		for _, v := range in.ExpressionAttributeValues {
			switch {
			case v.S != nil:
				date = aws.StringValue(v.S)
			case v.N != nil:
				n, err := strconv.ParseInt(aws.StringValue(v.N), 10, 64)
				require.NoError(m.t, err)
				bounds = append(bounds, n)
			}
		}
		require.Len(m.t, bounds, 2)
		sort.Slice(bounds, func(i, j int) bool { return bounds[i] < bounds[j] })
		var items []map[string]*dynamodb.AttributeValue
		for _, k := range m.sortedKeys() {
			item := m.items[k]
			if item[keyDate] == nil || aws.StringValue(item[keyDate].S) != date {
				continue
			}
			created, err := strconv.ParseInt(aws.StringValue(item[keyCreatedAt].N), 10, 64)
			require.NoError(m.t, err)
			if created < bounds[0] || created > bounds[1] {
				continue
			}
			items = append(items, item)
		}
		out = &dynamodb.QueryOutput{Items: items, Count: aws.Int64(int64(len(items)))}
	default:
		fail(w, fmt.Errorf("unsupported operation %v", op))
		return
	}
	w.Header().Set("Content-Type", "application/x-amz-json-1.0")
	require.NoError(m.t, json.NewEncoder(w).Encode(out))
}

func splitTarget(target string) (string, string, bool) {
	for i := len(target) - 1; i >= 0; i-- {
		if target[i] == '.' {
			return target[:i], target[i+1:], true
		}
	}
	return "", "", false
}

