func TestScratchDaysBetween(t *testing.T) {
	from := mustDate(t, "2020-01-31T23:00:00Z")
	to := mustDate(t, "2020-02-02T01:00:00Z")
	require.Equal(t, []string{"2020-01-31", "2020-02-01", "2020-02-02"}, daysBetween(from, to))

	same := mustDate(t, "2020-03-05T10:00:00Z")
	require.Equal(t, []string{"2020-03-05"}, daysBetween(same, same.Add(time.Hour)))
	require.Equal(t, []string{"2019-12-31", "2020-01-01"}, daysBetween(mustDate(t, "2019-12-31T12:00:00Z"), mustDate(t, "2020-01-01T12:00:00Z")))
	require.Nil(t, daysBetween(mustDate(t, "2020-01-05T00:00:00Z"), mustDate(t, "2020-01-02T00:00:00Z")))
}

func mustDate(t *testing.T, in string) time.Time {
	out, err := time.Parse(time.RFC3339, in)
	require.NoError(t, err)
	return out
}

func TestScratchEmitSetsDate(t *testing.T) {
	now := mustDate(t, "2020-06-15T12:00:00Z")
	m, svc := newMock(t, []string{"timesearch", "timesearchV2"})
	log := newLog(svc, now)

	require.NoError(t, log.EmitAuditEventLegacy(events.SessionStartEvent, events.EventFields{
		events.SessionEventID: "session-1",
		events.EventTime:      now,
	}))
	require.NoError(t, log.EmitAuditEvent(context.TODO(), &events.Session{
		<Type: "session.start">,
	}))

	require.Len(t, m.items, 2)
	for _, item := range m.items {
		require.Equal(t, "2020-06-15", aws.StringValue(item[keyDate].S))
		require.NotNil(t, item[keySessionID].S)
		require.NotNil(t, item[keyEventIndex].N)
	}

	// indexExists
	exists, err := log.indexExists("events", "timesearchV2")
	require.NoError(t, err)
	require.True(t, exists)
	exists, err = log.indexExists("events", "nope")
	require.NoError(t, err)
	require.False(t, exists)
}

func TestScratchMigrateAndSearch(t *testing.T) {
	now := mustDate(t, "2020-02-01T05:00:00Z")
	m, svc := newMock(t, []string{"timesearch", "timesearchV2"})
	log := newLog(svc, now)

	// seed events stored without the CreatedAtDate attribute
	seed := func(sid string, seconds int64) {
		_, err := svc.PutItem(&dynamodb.PutItemInput{
			TableName: aws.String("events"),
			Item: map[string]*dynamodb.AttributeValue{
				keySessionID:  {S: aws.String(sid)},
				keyEventIndex: {N: aws.String("0")},
				keyCreatedAt:  {N: aws.String(strconv.FormatInt(seconds, 10))},
				"Fields":      {S: aws.String(fmt.Sprintf(`{"%v":"%v","%v":"%v"}`, events.EventType, sid, events.EventTime, time.Unix(seconds, 0).UTC().Format(time.RFC3339)))},
			},
		})
		require.NoError(t, err)
	}
	before := mustDate(t, "2020-01-31T22:00:00Z").Unix()
	after := mustDate(t, "2020-02-01T02:00:00Z").Unix()
	seed("jan31", before)
	seed("feb01", after)

	require.NoError(t, log.migrateDateAttribute(context.TODO()))
	for _, item := range m.items {
		require.NotNil(t, item[keyDate])
	}

	history, err := log.SearchEvents(mustDate(t, "2020-01-31T00:00:00Z"), mustDate(t, "2020-02-02T00:00:00Z"), "", 0)
	require.NoError(t, err)
	require.Len(t, history, 2)
	require.Equal(t, []string{"jan31", "feb01"}, []string{history[0].GetString(events.EventType), history[1].GetString(events.EventType)})

	// the query must bind exactly one string (the date) and two numbers
	require.Equal(t, indexTimeSearchV2, aws.StringValue(m.lastQuery.IndexName))
	require.Len(t, m.lastQuery.ExpressionAttributeValues, 3)
	var strings, numbers int
	for _, v := range m.lastQuery.ExpressionAttributeValues {
		switch {
		case v.S != nil:
			strings++
		case v.N != nil:
			numbers++
		}
	}
	require.Equal(t, 1, strings)
	require.Equal(t, 2, numbers)

	// single day search
	history, err = log.SearchEvents(time.Unix(before, 0), time.Unix(before, 0).Add(time.Minute), "", 0)
	require.NoError(t, err)
	require.Len(t, history, 1)
	require.Equal(t, "jan31", history[0].GetString(events.EventType))
}
